sealed class TraditionalAlgorithmResult
{
    public string Display;
    public string Summary;
    public string TimingSummary;
    public string MethodVersion;
    public string AiPrompt;
    public string AiPromptSection;
    public string AiPromptVersion;
    public object Input;
    public object CalculatedFacts;
    public object Limitations;
    public object Provenance;
}

sealed class EmbeddedTraditionalAlgorithmEngine
{
    readonly WebBrowser browser;
    readonly JavaScriptSerializer serializer = new JavaScriptSerializer();
    bool ready;
    string loadError;

    public EmbeddedTraditionalAlgorithmEngine()
    {
        browser = new WebBrowser();
        browser.AllowWebBrowserDrop = false;
        browser.IsWebBrowserContextMenuEnabled = false;
        browser.ScriptErrorsSuppressed = true;
        browser.ScrollBarsEnabled = false;
        browser.TabStop = false;
        browser.SetBounds(-20, -20, 1, 1);
        browser.DocumentCompleted += delegate(object sender, WebBrowserDocumentCompletedEventArgs e) {
            if (browser.ReadyState == WebBrowserReadyState.Complete) ready = true;
        };
    }

    public Control HostControl { get { return browser; } }

    public void Start()
    {
        try {
            string script = LoadEmbeddedScript();
            script = script.Replace("</script", "<\\/script").Replace("</SCRIPT", "<\\/SCRIPT");
            browser.DocumentText = "<!doctype html><html><head><meta http-equiv=\"X-UA-Compatible\" content=\"IE=11\"></head><body>"
                + "<script>" + script
                + "\nfunction calculateTraditional(method,timestamp,options){return ZhanbuAlgorithms.calculate(method,Number(timestamp),options);}</script>"
                + "</body></html>";
        } catch (Exception ex) {
            loadError = ex.Message;
        }
    }

    static string LoadEmbeddedScript()
    {
        byte[] compressed = Convert.FromBase64String(WindowsAlgorithmPayload.Data);
        using (var input = new MemoryStream(compressed))
        using (var gzip = new GZipStream(input, CompressionMode.Decompress))
        using (var reader = new StreamReader(gzip, Encoding.UTF8)) {
            return reader.ReadToEnd();
        }
    }

    public TraditionalAlgorithmResult Calculate(string method, DateTime date, string optionsJson)
    {
        if (loadError != null) throw new InvalidOperationException(loadError);
        if (!ready || browser.Document == null) throw new InvalidOperationException("内嵌算法正在初始化，请稍后再试。");
        var epoch = new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc);
        long timestamp = (long)(date.ToUniversalTime() - epoch).TotalMilliseconds;
        object value = browser.Document.InvokeScript("calculateTraditional", new object[] {
            method, timestamp.ToString(CultureInfo.InvariantCulture), optionsJson
        });
        if (value == null) throw new InvalidOperationException("内嵌算法没有返回结果。");
        var root = serializer.DeserializeObject(Convert.ToString(value)) as Dictionary<string, object>;
        if (root == null || !root.ContainsKey("ok")) throw new InvalidOperationException("内嵌算法返回格式无效。");
        if (!Convert.ToBoolean(root["ok"])) {
            throw new InvalidOperationException(root.ContainsKey("error") ? Convert.ToString(root["error"]) : "算法计算失败。");
        }
        var result = root["result"] as Dictionary<string, object>;
        if (result == null || !result.ContainsKey("display")) throw new InvalidOperationException("内嵌算法结果缺少正文。");
        return new TraditionalAlgorithmResult {
            Display = Convert.ToString(result["display"]),
            Summary = result.ContainsKey("summary") ? Convert.ToString(result["summary"]) : "",
            TimingSummary = result.ContainsKey("timingSummary") ? Convert.ToString(result["timingSummary"]) : "",
            MethodVersion = result.ContainsKey("methodVersion") ? Convert.ToString(result["methodVersion"]) : "",
            AiPrompt = result.ContainsKey("aiPrompt") ? Convert.ToString(result["aiPrompt"]) : "",
            AiPromptSection = result.ContainsKey("aiPromptSection") ? Convert.ToString(result["aiPromptSection"]) : "",
            AiPromptVersion = result.ContainsKey("aiPromptVersion") ? Convert.ToString(result["aiPromptVersion"]) : "",
            Input = result.ContainsKey("input") ? result["input"] : null,
            CalculatedFacts = result.ContainsKey("calculatedFacts") ? result["calculatedFacts"] : null,
            Limitations = result.ContainsKey("limitations") ? result["limitations"] : null,
            Provenance = result.ContainsKey("provenance") ? result["provenance"] : null
        };
    }
}

