    static readonly string[][] QIAN = {
        new string[]{"第一签","大吉","飞龙变化","飞龙变化喜逢时，此日升腾果遂期。谋望求财多吉庆，求官进位更无疑。","冲霄志气满心胸，君子应非久困穷。此行当际风云会，万人头上逞英雄。","三阳交泰转鸿钧，瑞气迎门万事新。岁稔时登财禄旺，又添人口喜相亲。","世间大礼是婚姻，天配如何悟世人。人若自知天理合，何须着意问天神。","偶失资财莫怨天，要知踪迹在南边。过时终有传音信，莫把平人作盗冤。","未发文书不用瞋，公厅虽直事难伸。不如散却心头火，免得将钱送别人。","卦直飞龙莫问亲，千山万水几艰辛。直教明月团圆处，西出阳关见故人。","焚香祷告意精专，惟在君心作福田。寿算天曹曾注定，何劳私下保安痊。","占家宅平安，病者立痊，六甲生男，行人立至，官有理，失物可寻，婚姻可成，出行吉利，求官必达，求财大遂，田蚕大熟，六畜兴旺，百事大吉。"},
        new string[]{"第二签","中下","虎出大林","虎出大林须动众，众人见了却忧疑。虽然未必伤人命，亦主虚惊事可知。","不平天理强支持，妄作从来是祸基。君子安贫终有道，莫教失计被人欺。","久淹陋室欲更新，争奈伊家少福脉。不惮虚惊忧怪梦，更防小口及阴人。","乍时相见好容仪，谁料中间一半非。不是婚姻休作对，何如撒手且回归。","只为当初不小心，资财已失复何寻。直教月尽寅申日，才有傍人说信音。","只好安居守运时，莫经官府受鞭笞。劝君休管人闲事，惹得愁来悔后迟。","雁杳鱼沉信息稀，空劳望断白云迷。相逢若遇寅辰日，鹊噪檐前人马归。","闹中得病静中安，莫作寻常一例看。有愿在心宜早赛，免教积热变脾寒。","占身不宜出入，失物难寻，病者作福，行人有信未至，求财迟，小口有灾，六甲难产，官事和劝，求官未达，婚姻难合，六畜田蚕半熟。"},
        new string[]{"第三签","大吉","否极从今","否极从今喜泰来，龙泉磨拂旧尘埃。莫信守己无他望，闭户深居也获财。","几年踪迹在江湖，名利才成出困途。此日相逢官贵力，好看春色满皇都。","莫忧家宅久淹留，天理於人岂有偏。但肯从前更改过，管教财谷胜常年。","有缘造物自安排，休叹无缘事不谐。此际好听琴瑟韵，莫教夜雨滴空阶。","几年沙里去淘金，失却才知枉费心。目下欲寻难得见，直逢艮后有知音。","偶遭横事迫躯身，冤枉如何诉得伸。自有神明空里佑，不教善者作囚人。","历涉江河几万重，家乡回首白云笼。从来也有阴功护，人在春风和气中。","刚强狼戾惹凶灾，谴责肌肤瘦似柴。若合道心从革过，枯枝花叶一时开。","占家宅人口大利，病宜作福，官事有理，求财遂意，六甲生男，求官必达，行人即至，六畜兴旺，田蚕大熟，身体大吉，婚姻可成。"},
        new string[]{"第四签","中下","劳心费力","劳心费力欲成功，待得花开一阵风。须藉东君轻借力，望中别有一枝红。","用尽机谋事不成，如今休要问前程。直待金乌到坤震，自然荣显利名兴。","无由闲事费支持，枉用贪心不见机。畜产损伤犹小失，更防人口有惊疑。","婚姻到日不须寻，何必区区枉用心。有意种花栽不活，等闲插柳却成林。","吃辛受苦钻资财，谁想今朝灰受灾。得失富贫皆由命，如今不必乱疑猜。","自古刚强解悟身，谁知有理反遭嗔。如今未必官刑责，何不私和做好人。","去时指望采黄金，回首家乡路转深。今日早知人事别，当初何似莫贪心。","但知动作是真奇，不想贪心惹祸基。空使七情伤本体，早求善力保无疑。","占家宅人口有灾，心失脱，求财未遂，失物不见，即宜急寻，行人未至，病者重，作福求官未达，六甲有惊，田蚕半熟，六畜宜保，婚事不成，官事和。"},
        new string[]{"第五签","大吉","行船风顺","行船风顺去无疑，利涉江津正遇时。万里长程知可到，所谋遂意事如期。","欲求动止莫怀疑，名利求寻莫待迟。但得便中须速去，休教蹉过运和时。","家门兴旺福神多，人口无灾百事和。春夏累沾些小悔，秋冬喜气自然多。","百岁婚姻一日成，今朝何事苦调停。两边相许无余事，便好承欢通娉婷。","昨日扁舟过洞庭，知君心下不安宁。相应失却凡间物，终有踪由莫用惊。","理直何须问上真，纵经官府不遭嗔。虽然目下多惊恐，保汝平安百事伸。","归期限促恨悠悠，争奈淹留事未周。若得福神添力佑，轻帆风送岸头舟。","谁觉灾来疾似风，卢医扁鹊枉施功。何知一愿答天地，再与添筹作老翁。","占家宅人口大吉，求财有喜，失物可寻，病者渐退，行人将至，官事有理，婚姻可成，田蚕六畜兴旺，占身作福吉，求官必达，六甲生男，事大吉。"},
        new string[]{"第六签","下下","鸳鸯分飞","鸳鸯阻隔两分飞，谋望求财未得时。守旧却宜休改革，如今进退尚迟疑","名利从来不易求，忙忙世事水中鸥。天公不欲人贪着，枉使浮云空白头。","指望今年百事昌，谁知因小惹灾殃。如今若得人财好，重告家神灶愿香。","不将年命合相同，勉强求成岂利通。纵若有缘成一处，终须离别各西东。","失却凡财问圣真，汝今莫把众人嗔。天曹料定分毫定，衣食随求不害身。","休听人唆入县衙，两边徒尔结冤家。不如撒手平和去，免得阶前叫老爹。","去时多有弟和兄，岂料中途失伴群。阻滞未来终久到，何须每日倚柴门。","妻占夫兮夫占妻，终朝必定守孤栖。父兄伯叔占男子，患难虽沉尚可医。","占家宅有口舌生灾，失物不见，官事宜和，求财未遂，求官未达，病祭家神，行人未至，六甲生女，田蚕半熟，六畜保吉，占身迟滞，婚姻不成。"},
        new string[]{"第七签","中上","枯木逢春","枯木逢春色欲华，顿然枝盛长萌芽。时人莫作为柴砍，直待春深又吐华。","久在山中待好音，无人拔采说知情。如今借得东风力，叶茂花繁覆地阴。","淹滞消除正可夸，福星一点照君家。从今莫听傍人说，树正何愁日影斜。","几年久坐没人招，今日枯枝长嫩条。自是婚姻千里合，无缘对面路迢遥。","分明失物在东方，不解追寻室里忙。若还更迟三五日，他人落得嘴头光。","新事伤人旧事成，劝君休要逞高能。平心自有宪台上，此地从来不可登。","音书许送到君家，争奈人情事未谐。直待三阳回马后，忽然衣锦到门阶。","无灾不肯念弥陀，有病才思旧愿多。若肯尽心从改过，不教善者见阎罗。","占家宅小口有灾，病者作福，占身忌小人侵等，失物急寻，求财未遂，行人有信至，求官未达，田蚕半熟，六甲生男，六畜保吉，婚姻可成。"},
        new string[]{"第八签","下下","渔舟上滩","因见渔舟上逆滩，渔舟泊此且盘桓。前滩过了浑无事，更有后滩过更难。","命里无时不必求，何须日夜泛鱼舟。红鳞祇在秋波内，用尽心机不上钩。","不能安分每贪图，惹得家神祸事多。春夏忧愁人口病，秋冬又忌损田禾。","傍人只说两相当，难测胸怀抱虎狼。面好怎知心不好，不知独枕外藤床。","皆因为小失驴牛，触在心头整日忧。人眼不如天眼见，分明教汝莫贪求。","得和阑处且和阑，到处人心有恶奸。莫信酒中胡说易，岂知台上对词难。","一心常挂两头忧，路阻关心不自由。惆怅几多冤恨事，更无消息到扬州。","只因小事恼心怀，惹得忧疑怪病来。急向静中求福善，莫教加谴堕尘埃。","占家宅人口有灾，自身防口舌，病作福，失物不见，求财未遂，行人未至，官事失理，求官未达，田蚕半熟，六甲难产有虚惊，六畜宜，更动婚姻难成。"},
        new string[]{"第九签","中平","春兰秋菊","兰芳春景真堪爱，菊吐青香色又佳。乾坤各自为情意，不解东风次第开。","昔曾许汝到春来，岂料营为意不谐。且待菊梅开绽月，依然名利两全哉。","指望家和万事成，年来忧闷几曾伸。因和不把家神敬，门户无人有向声。","婚若成时待月圆，不须心下意悬悬。虽然好段姻缘事，争奈他人尚未坚。","自失如何怨老天，神公岂肯为财怜。伊君要听真消息，不在明年在后年。","戒伊不用苦贪嗔，恐有文词到讼听。凡事抽身归去好，闭门静坐作贤人。","久去虽然音信稀，汝今何用意踌蹰。菊兰自有开花日，各自根苗等待时。","此处恹恹怨满怀，未逢良药事难谐。平安等到三更后，祸去从交福降来。","占家宅防小口有灾，阴人有灾，宜作福，失物难寻，病者作福，求财半遂，行人有信，官事留连未达，六甲未产，六畜旺相，婚姻可合迟。"},
        new string[]{"第十签","下下","游蜂作蜜","不论平地与山尖，无限风光总被占。采得百花成蜜后，与谁辛苦与谁甜。","托人去干心中事，早早回头归故乡。口好怎知心不好，痴心且去受灾殃。","今岁田蚕半吉祥，夏秋又忌损牛羊。冬深人口宜禳保，更忌凶人夜入墙。","野草闲花莫恋迷，一朝乐极便生悲。收心且待婚姻事，莫惹傍人说是非。","失去资财莫怨天，谁教贤者只贪眠。情知已入他人手，不在芦花浅水边。","世间难戒是贪嗔，因笑螳螂不见机。只恐鸣蝉遭汝捕，不知黄雀后头随。","艰难经涉万重山，心事忙忙意未还。又恐路途人毒害，几多凶险在其间。","恶病临身没奈何，看看沉重见阎罗。如今若要凶星退，速请高僧理剎那。","占家宅防有灾，占身平安，失物不见，防口舌，求财耗散，行人未至，病者主重宜作福，官事未了，求官未达，六甲生女，婚姻不成，有口舌，田蚕半熟。"},
        new string[]{"第十一签","大吉","囚人出狱","囚人出狱争讼了，却买甜瓜上酒楼。遇见故人同畅饮，酒钱还了又相酬。","埋沉踪迹未亨通，今日承恩谢上穹。改过前非行大道，自然财禄尽雍容。","马旺人兴百事宜，田蚕十倍在秋期。但防阴小生灾疾，见喜无忧不可欺。","前世因缘会今生，莫为资财起爱憎。若有贵人提拔处，好攀月桂上云层。","莫赖平人暗里责，分明落在市桥西。如今有靠神灵佑，失物还须不得齐。","从来惧法怕官方，事到头来险几场。自有高人亲眼盼，不须惆怅虑心肠。","几年相别到门闻，今日他乡遇故知。归意急如江上浪，只争来早与来迟。","几年才脱是非门，岂料天灾又染身。若更不求神力佑，留连日久困尘埃。","占家宅添人口，占身无事，失物可寻，病者服药，求财大获，行人立至，官事有理，婚姻可成，求官得位，六甲生男迟，田蚕大熟，六畜兴旺，凡事大吉。"},
        new string[]{"第十二签","下下","风卷杨花","杨花风卷无消息，却似襄王一梦中。夜静月明风细处，空飘零落惹芳丛。","不依时运强求财，心地高平汝自裁。若要妄为非礼事，不招祸至惹天灾。","路险身衰暮夜归，谨防目下闹中非。家中小口招灾祸，六畜田蚕今岁亏。","未有姻缘莫主张，两边年命少相当。媒人本是瞒人汉，谋得成来不久常。","原来不是自家财，何用叨叨着意猜。不想破财又折本，总然寻得也招灾。","横事无忧蓦地来，心中愁闷几时开。如今不惹和为贵，免得将钱到宪台。","鱼沉鸦杳去无踪，困旅穷途阻不通。万里故乡归未得，阳关回首白云浓。","梦入幽冥路已赊，投神空自惹咨嗟。落花有意随流水，流水无情恋落花。","占家宅不利，阴人小口不测，有灾病者凶，宜保福，求财无，行人未至，官事和劝，求官未达，田蚕半熟，六甲难产，婚姻不成，六畜宜保安。"},
        new string[]{"第十三签","大吉","开花结子","开花结子喜逢时，赖得春工造化机。所望求谋皆遂意，永锦还乡事可期。","玉体冰肌不肯移，真心惟有岁寒知。如今喜得阳和至，花落依然果满枝。","今年不似去年贫，财宝重添遇贵宾。人口完成无贼盗，平安赛过九州人。","女貌郎才世所稀，前缘修定不须疑。如今但得他人肯，便好将钱过定期。","浮财失去问谁将，莫把平人要细详。汝正的然西向坐，原来此物在东方。","少辈般唆事未宁，如今不用把心惊。公厅自有真明镜，曲直无灾免杖刑。","行人心急意徘徊，阻路牵连尚未回。寅卯待交辰巳日，依然平地一声雷。","天星不顺致灾愆，有病占身不损年。若得明师及谬语，不如祈福谢苍天。","占家宅平稳，占身大利，失物可寻，病者得痊，求官得位，行人便至，官讼有理，求财遂意，六甲生男，田蚕大熟，婚姻可成，添人进口，六畜旺相。"},
        new string[]{"第十四签","中平","龙蛇混杂","龙蛇混杂最难分，未得风雷变化鳞。一日升腾归北海，那时方得现龙神。","两头事意尚蹉跎，只好随缘守分过。但得时来不多久，眼前求得也消磨。","不崇香火不修身，来问家间事未伸。若要财兴人口旺，除非安过旧家神。","偷婚不与众人知，失福违伦悔后迟。若不被人强古害，也遭官府受鞭笞。","失却浮财莫哭穷，要寻目下不能从。直教风冷寒霜至，方见傍人说实踪。","人鬼交横事求和，难分曲直及奔波。不如忍却心头火，免得浑身受折磨。","行人去后未还家，同伴台连有怨嗟。要见直逢壬癸日，故人方始出天涯。","玉石难分假与真，阴阳玲热未均宁。早把心香焚一灶，免得阳间作阴人。","占家宅人口不宁，占身不宜出行，失物难寻，病者星辰不顺，田蚕半收，求财未遂，行人未至，婚姻难成，口舌官事失理，求官未达，六甲忧疑，六畜更变。"},
        new string[]{"第十五签","上上","一轮明月","月满今宵离梅边，时人感仰丽青天。清光烁处群星散，君子营谋便得官。","此去相逢贵客邀，莫嗟天外路迢遥。平地任汝营求意，云有天梯渡水桥。","保得身安莫问钱，好香焚灶谢苍天。田蚕六畜多兴旺，管取今年胜旧年。","前生注定是姻缘，女貌郎才并少年。要肯坚心答天地，管教夫妇共团圆。","失物踪由过北厢，如今休要乱胡详。来朝自有傍人见，便靠神明保吉祥。","汝本聪明特达人，偶逢淹滞损精神。云收雨散中宵静，现出蟾光四海明。","去时曾约便相逢，今日音书又不通。阻滞淹留三五日，管教财阜乐时丰。","中心有事意难为，如若为之君子知。自是善财难割舍，舍之祸去福来随。","占家宅平稳，占身大吉，失物不失，病者不妨，作福保吉，求财遂意，行人立至，官事有理，求官必达，六甲生男，婚姻就成，田蚕六畜兴旺，凡事大吉。"},
        new string[]{"第十六签","下下","浊油点灯","浊油点灯灯易灭，才挑得起又衰微。长心挑尽空劳力，何不抽身早去归。","履危渡水两艰难，万计千谋名利怪。守分安贫宜忍耐，忙忙劳碌不如闲。","只因不肯敬神明，惹得家中事不宁。今岁欲除灾与祸，除非重整奋家神。","才方说起便搂搜，即是姻缘不到头。如今略得言相许，又恐他人暗里谋。","乍失资财莫便嗔，宽怀休要怨他人。归来且把心头忖，破了浮财免害身。","万事无过一认真，何须苦苦说艰辛。不如急早回头去，到彼须防鬼弄人。","身衰力弱路难行，咫尺家乡万里程。宜向道中求善福，免教风雨送秋声。","忧危莫枉费资财，流水无情去不回。半点残灯光欲尽，更遭一阵猛风来。","占家宅不宁，占身宜守旧，失物不见，官事失理，病者凶，求财未遂，婚姻不成，六甲生男有忧，六畜有损，行人防盗，凡事不利。"},
        new string[]{"第十七签","中平","当忧不忧","当初得意翻成失，今日忧危事不危。若遇贵人相引接，千年枯木再生枝。","贪多偏惹祸临身，名利从来未是真。但得优游家道乐，知他谁是百年人。","莫将怪梦作闲愁，休听邪师祸不招。自是行藏天理合，岂因危小病难消。","不须勉强为资金，姻运来时那用寻。卒急要成非好事，知人知面不知心。","只因懒散不收藏，失去之时便有藏。用意早寻容易见，更迟三日往西方。","烧香祷告意精神，若问官灾事不成。自有贵人提举力，虎头蛇尾不须惊。","不用人前问信音，行人在外有归心。虽然钱物无多少，但得平安直万金。","灾来不是自家招，何用将钱向鬼烧。但要平心答天地，依然平稳过寒潮。","占家宅阴人小口有灾，占病不妨，求财半遂，行人未至，占身守旧，求官必达，官事缓慢吉，六甲生男，田蚕大熟，婚姻迟吉。"},
        new string[]{"第十八签","下下","笼开鹤去","养汝原来岁月深，笼开不见意沉吟。相应只在秋江上，明月芦花何处寻。","本来无分作仙翁，为爱飞禽使罩笼。不合脱身天外去，方知贪欲尽成空。","旧年不利损多般，今岁缘何又不安。畜产田蚕无一倍，更忧火盗事相于。","姻缘心许不知非，怎好贪欢逐汝归。仁看始知林里雁，五更天晓各分飞。","闲时不把藩篱修，失却浮财更惹忧。财物已落空消化，如今那去讨踪由。","三司台上始知非，图圄围中悔后迟。若得皇恩天赦到，开牢放出罪人归。","利名赠蹬意徘徊，身阻他乡未便归。望断长江无信息，却知鲍老送婴孩。","天星不顺病难安，每日恹恹改旧颜。服药求神无应效，许来心愿不如迟。","占家宅不安，占身失脱，失物不见，阴小生灾，求财无，行人未至，六甲生男，官事失理，求官未达，出行不利，田蚕半熟，六畜损失，病者星辰不顺，久愿未还。"},
        new string[]{"第十九签","大吉","云行雨施","云行雨施春正深，谋望求财总遂心。争讼见官多有理，贵人喜庆自相寻。","时逢暖律景和平，谋望求财总遂心。若要营为当此际，脱身易服取功名。","春耕夏种又秋收，人事平安不用忧。早去脱身须谨慎，堤防小辈弄无由。","归家便把鸾房整，好听鸣琴有凤声。天付姻缘更和合，伊今不必问前程。","劝君更改不依从，失去求神问吉凶。子午方头人旺处，好教仔细问来踪。","莫信人来话短长，虽然失理也高强。若逢官贵微加力，如日光明大吉祥。","久住他乡未到家，偶然流落在天涯。一朝待遇龙行雨，枯木依然满树花。","来如风雨去微尘，病者恹恹尚未醒。好把心头愿早赛，免教疾病苦缠身。","占家宅防失脱，占身吉，失物急寻，行人有信，求财遂意，官事有理，婚姻可成，六甲生男，六畜兴旺，田蚕大吉。"},
        new string[]{"第二十签","下下","有舟无楫","有舟无楫难撑载，更被漂流向海中。嗟叹世人应不足，误人如此走西东。","千谋万计事难成，枉走关山万里程。孰若收心且忍耐，不然事主反忧惊。","去年指望今年好，今岁缘何又不宁。祇为旧勿多怪异，却教疑忌损人情。","许了因何又不同，只应年命不相同。莫教勉强心无定，又恐相逢是梦中。","闲时不肯细堤防，失去如何空自忙。山涧有踪寻不见，莫思音信在谁傍。","官事从来好劝开，纵怪理直不须来。莫教成事难回避，只恐淹留到宪台。","损体伤身只为财，他乡羁绊未回来。行人在路防官事，家下仍忧火盗灾。","破舟过海又遭风，失楫逢危在险中。问卜求医都是妄，不如急景扣阴功。","占家宅人口有灾，占身有口舌，失物不见，病者难痊凶，行人未至，官事宜和，求官未达，婚姻反悔，六甲生女，田蚕半收，六畜有灾。"},
        new string[]{"第二十一签","大吉","鲲化为鹏","鲲化为鹏海浪翻，阴阳交泰太平间。庶人蓦有凌云志，平地雷声启垫还。","几年流在波涛内，未得风雷志气高。今日脱身才变化，应知万里任游遨。","预宜更改旧门庭，马旺人兴百事宁。不但田蚕收十倍，更於四处任经营。","幼男小女两相宜，配合婚姻似火催。此际好求鸾凤偶，迁延蹉过悔来迟。","东北方头水路行，踪由寻见物还生。莫教怠慢多疑虑，财散人离有改更。","初然心事尚孤疑，到底渊清见石堤。终有贵人添气力，不教罗网罩鲸鱼。","行人久无鱼雁音，愁煞家眷梦里寻。天尊殿前虔心祷，立教行人现门庭。","七情伤体惹灾来，皱却双眉闷不开。作福祷神求保护，免教人眷起悲哀。","占家宅进人口，占身大吉宜更改，病者保福安痊，求财遂意，行人立至，官事有理，求官必达，婚姻可成，六甲生男，田蚕大熟，六畜兴旺，凡事大吉。"},
        new string[]{"第二十二签","上上","凤凰出林","凤凰飞出林间去，展趋飞来异众禽。一旦身荣朝上阙，曰方钦羡尽闻名。","几年静坐守闲居，景物萧条家道虚。此去时通开泰运，不求名利自寻伊。","好整新居换旧巢，远离群小免相嘲。时和无事平为福，岁稔何能落下稍。","百年夫妇似呜琴，静中好听凤鸾鸣。休教良姻佳期路，等到天寒失雁群。","只因自己欠遮围，失去何如得自归。便要经官方得见，不教久后受人亏。","本为毛羽惜朱衣，恨入深林被鹊欺。今日奋身腾碧汉，从他鼠鹊哂何时。","去人归后促行装，离了他乡在路傍。牛马下旬音信到，平安无事不须忙。","数载淹留运未通，灾星正照汝家门。谁知却有穹苍助，保汝痊安谢上穹。","占家宅人口平安，占身宜作福，官事有理，求官必达，求财半遂，婚姻难成，田蚕大熟，六甲生男，病者得痊，六畜兴旺。"},
        new string[]{"第二十三签","下下","花开遭雨","种得桃株满院东，花开遭雨又遭风。当初指望收桃吃，到了如今只是空。","几载蟾宫折桂枝，未逢时节使空回。何期等到花开日，又被连天大雨催。","旧居不利向新搬，不肯搬移不得安。万事本家人力薄，春心又忌小人干。","因观面好不知心，枉属良媒费万金。只为眼前欢共乐，那知祸起在娼淫。","何用叨叨着意猜，情知不是自家财。须凭天理求安乐，非义从来是祸胎。","横事临门岂可进，堤防小口笑中刀。迁延不肯平和了，终久缠身到宪牢。","关山迢递路艰难，去了行人尚未还。好向神天修善福，免教身入鬼门关。","真病从来无药方，莫教沉重却慌忙。伊人不告神天佑，老者淹留少者亡。","占家宅阴人小口有灾，占身防口舌、失物不见，病者作福，求财未遂，行人未至，官事失理，求官未达，婚姻不成，田蚕半熟，六畜有损，行人不利，六甲生男。"},
        new string[]{"第二十四签","大吉","明月当空","明月当空处处辉，朗然照耀破昏迷。所谋显达家门吉，此日荣华正及时。","心欲清闲事未闲，失时无处把身安。如今却得青云路，不用天梯步广寒。","汝家无事不须疑，夜梦如何有准期。人眷安然无别虑，堤防暗里小人欺。","婚姻本是合团圆，不必慌忙心下悬。自是有缘相会日，管教男女共完全。","如今已到别人边，莫把平人作盗冤。踪迹有方终久出，虽然得见也难全。","龙虎相投事有佳，一轮明月照天涯。已分玉石何须虑，不必君心乱如丝。","相望行人在目前，如何归兴许迁延。要知何日音书到，明月团圆人自圆。","从来祸福两无门，总是人招不必论。正好当天投首谢，莫教夜月照孤魂","占家宅失脱，占身宜静守旧吉，失物不见，病者作福，求财获，行人信至，官事有理，求官必达，六甲生男，婚姻吉迟，六畜田蚕大熟，凡事大吉。"},
        new string[]{"第二十五签","下中","求谋未遂","求谋未遂如君意，欲望青云路转赊。且宜守旧方为吉，他时必定见荣华。","运未亨通莫强求，眼前求得也成忧。不如守旧依稀过，欲得荣华在后秋。","是非重迭起虚惊，畜产衰微百怪兴。若要荣为不如意，堤防寇盗入门庭。","此亲虽好汝无缘，休要耽迷惹祸愆。改革待伊缘分到，不拘迟晚但心坚。","遍寻踪迹少人知，不若回身且待迟。等到月残申酉日，要知失物在斯时。","若求动用不须来，守分依稀可免灾。官事宜和方是吉，两家才免挂心怀。","去年平稳不须疑，只为财中所见迟。若问归期何日到，虎头蛇尾报君知。","自古人生七十稀，为图名利染灾危。荣枯修短皆前定，保得身全也损皮。","占家宅有失脱，人口生灾，占身守旧，病者重，失物不见，求财未遂，官事和劝，求官未达，婚姻不成，田蚕半熟，六畜损失，六甲生女，行人未至。"},
        new string[]{"第二十六签","大吉","安居兴旺","安居兴旺进钱财，天上生云地震雷。禄位高迁尤显达，荣华富贵入门来。","运至何须出远邦，自然财宝聚伊傍。利名岂在随人欲，却笑浮生空自忙。","敬神如在福人欢，宅舍光明百事安。不但田蚕俱得旺，仍於火盗不相干。","撞着姻缘那用媒，有心何必急相催。皆非今日能相见，五百年前结会来。","东西小路旧人家，失去踪由在彼遮。死物仍然生活物，不须怨恨惹咨嗟。","贵人相应事无干，和气融融共一团。汝事抽身归去好，任他狡猾百千端。","骏马长途紧着鞭，三朝两日便朝元。京华作个逍遥客，一纸音书下九天。","凶星已退病将痊，尽是先亡作祸愆。一炷信香通表过，忽然久病脱身田。","占家宅防小人相弄，占身无事，失物要见，求财更变，行人便至，官事得理，求官必达，占病不妨，六甲生男，婚姻可成，田蚕大熟，六畜兴旺，凡事大吉。"},
        new string[]{"第二十七签","下下","家宅惶惶","家宅惶惶主不宁，盖因先祖作灾述。且宜作福求禳度，更谢家间奉祀神。","枉使贪心惑执迷，不依安分强施为。一朝起祸萧墙内，拿得鹰来鹊已飞。","不祥夜梦作虚惊，鸡犬无端作怪声。非是家神专降祸，只因不祀旧亡灵。","古来嫁娶择三堂，卒急求成岂善良。若不三思无主意，后来难悔受灾殃。","家神不旺惹非灾，失去如何是汝财。不想自家时运拙，何须心下乱疑猜。","事须有理见官迟，若不私和有是非。事到公厅难解脱，文词反覆更难为。","去后三般不自由，门庭消索玲如秋。行人一去无音信，且到春来莫要忧。","命蹇时乖处是非，何须临难告神祇。不如早赛心头愿，莫负当初起许时。","占家宅自身防口舌，失物不见，病者沉重，求财无，官事失理，求官未达，行人未至，六甲生女有灾，婚姻不成，田蚕六畜有灾防盗。"},
        new string[]{"第二十八签","上上","贵人接引","贵人接引喜更新，口舌官灾远户庭。病者从今身体健，求财谋望总亨通。","积善之家庆有余，吉人自有福星随。求谋必定从天理，任是凶危也荡除。","莫因岁事起疑心，纵有浮云无人阴。不但人财两兴旺，更於火盗不相侵。","良朋相对说知音，月郎星辉酒味醇。此际好听琴瑟韵，休教蹉过到来春。","东北方头古路通，逢人更好问知风。君今休要辞劳苦，仔细眼寻未落空。","不用投词事已开，一团和气入门来。见官终是蒙官力，何必忧疑虑远灾。","若问行人几日归，更待三三五五期。若遇贵人扶力气，不须惆怅虑灾危。","作善修因宿事缘，君家阴德答苍天。天医自有灵丹药，些小淹留病得痊。","占家宅人口吉，自身安，失物不失，行人半路，公讼平安，求财必遂，六甲生男，婚姻和合，求官必达，病者痊愈，田蚕大熟，六畜添进。"},
        new string[]{"第二十九签","大吉","阴阳道合","阴阳道合事亨通，还如人在月中行。琴瑟调和门户吉，富贵荣华百事亨。","十年勤苦在灯窗，蓦地番身入选场。喜得当朝用贤士，如今天府姓名香。","敬神自是答天心，神喜人欢祸不侵。岁小淹留无挂碍，田蚕十倍在秋深。","赤绳缚足记前缘，不用求谋事已成。明月夜深丝竹下，静中好听凤凰声。","失物虽然路已赊，未沉深虏没姻涯。急寻自有神明在，不怕千重篱壁遮。","汝是人中最吉人，胡为胡作损精神。阳德不如阴德好，徒教到底不沾身。","关山迭迭路崎岖，客旅忧心挂两偶。今日忧危都散尽，忽然归兴到门闾。","天灾数定不由人，何用叨叨渎鬼神。自是灾星当满日，依然体旺久精神。","占家宅人口平安，失物急寻，病者保禳不妨，先凶后吉，行人至，求财半遂，求官必达，官事不成，婚姻成，六甲生男，田蚕六畜旺相。"},
        new string[]{"第三十签","下下","月被云遮","花正吐时遭夜雨，月当明处被云遮。寄言桃李休相笑，一日云开自有时。","世间谁及汝聪明，争奈时乖事未成。且在灯窗成旧业，待教秋后问功名。","有心斋戒不宜开，恐惹非灾横祸来。归去依然修正果，免教人眷起悲哀。","以前姻偶本来缘，却被傍人说乱言。今日欲求难得就，不如归去待迟延。","有心人算没心人，失却资财却问神。踪迹有时终久在，不须发恶惹人嗔。","本来无事惹非灾，只为他人做出来。若到公厅难理直，不如私下劝和开。","人去他乡未到家，两头心绪乱如丝。谁教云散蟾光现，方见人财免叹嗟。","病已临身脱则难，求医无效减容颜。须知旧愿宜先赛，可免身淹枕席间。","占家宅只宜守旧谨慎，失物，防口舌，病者作福，求财未遂，行人未至，官事失理，婚姻难成，六甲生女，求官未达，田蚕半熟，六畜损失，走失难寻。"},
        new string[]{"第三十一签","中平","心事冲冲","心事冲冲常不一，坐得身安又不安。所作所为全未遂，却如明月被云拦。","自家心下意慌慌，争奈他人心未忙。财物如山皆分定，劝君守旧待时光。","伊家何事起悲哀，南北方头犯上来。酬谢福神更改吉，不然安得皱眉开。","花言巧语岂真情，浪蝶狂风未可亲。不信但看园里物，一番风雨便生心。","失去如今徒自忙，等闲不肯细堤防。要知踪迹归何处，直待中旬夜月光。","事到心头割似刀，不如忍耐莫强操。任他车马团团转，局势虽赢着不高。","欲问行人尚未还，归期重隔几重山。荣鞭赢马登程去，只为丝丝有贵攀。","家宅无神鬼祟多，病人恍惚意蹉跎。如今若要身安健，除是将财舍剎那。","占家宅人口平安，失物不见，病者保禳，求财未遂，行人未至，官事留连，求官未达，婚姻难合，六甲难产，田蚕半收，六畜保吉。"},
        new string[]{"第三十二签","下下","众星侵月","众星侵月事须防，小口灾临主祸殃。病者修禳能减半，志心祈福谢穹苍。","古来名利与兵机，谋者虽多得者稀。不若收心且忍耐，必然失计被人欺。","阴眷频灾事若何，祇因家宅鬼神多。如今若要平安日，除是寻僧礼达摩。","本来姻偶得团圆，争奈傍人起祸端。若要事成宜早速，不然迟慢守孤寒。","分明失物在东方，知者虽多不肯谈。若是钱财难得见，己分骨肉又酸醎。","小辈无端弄是非，却教有理反成亏。如今急早平和了，莫待牵连入狱围。","去时急速转时迟，何事迁延到此时。争奈途中身有阻，早求洪福保灾危。","星辰不顺祸临身，莫待淹留变骨蒸。早修禳灾可及脱，免教人眷举悲哀。","占家宅人口不吉，占身防口舌，失物不见，占病沉重，求财未遂，行人未至，官事失理，求官未达，六甲不吉，婚姻大破，田蚕半收，六畜损失，人口作福保禳。"},
        new string[]{"第三十三签","大吉","龙剑出匣","新磨龙剑快锋芒，动起冲牛孰敢当。又向携持今在手，英雄猛烈倍寻常。","未逢雷焕送归渊，百炼千磨受苦煎。此志化龙知有日，峥嵘头角上青天。","华居新改业初收，又值春期事满畴。耕种定收十倍旺，更为官贵事和周。","自古婚姻岂偶然，有缘万里也通传。如今正好修姻契，莫把琵琶送别船。","暂时失去莫惊忧，急急归家计后求。西北方头去路处，有人对面说踪由。","别人起事偶干伊，何用怀疑别是非。自有高人说公道，不教善者受刑亏。","剑出铜函快似锋，行人已在半途中。若逢子午归期到，休虑关山几万重。","皮肤消瘦骨还坚，每日恹恹未得痊。但要存心报忠孝，何忧小病损天年。","占家宅人口平安，占身先有口舌，失物急寻，以后寻见，求财遂意，行人便至，官事有理，求官必达，婚姻可成，六甲生男，田蚕大熟，六畜兴旺，病保禳。"},
        new string[]{"第三十四签","下下","病龙行雨","病龙行雨怕虹霓，有病占身事不宜。变化升腾须有日，但宜守旧待明时。","未动春雷势力衰，安然平地起风雷。饶君空有拿云手，弄巧番成拙事来。","怪梦频频心下忧，缘何啾唧损驴牛。但知自己惟心欲，不念亡先隋九幽。","姻缘一事在秋天，莫信傍人弄倒颠。要折野花将自看，休教认作并头莲。","户乏门衰祸事临，资财失去便难寻。要知踪迹归何处，只在山前及树林。","官事从和便好休，莫教自己作牢囚。劝君且把心量度，亏你些见有甚差。","去时曾约便回还，等到如今夜月残。途路有灾宜作福，保安才出万重山。","事情伤体有灾来，祟祸临门遣不开。要好求神还旧愿，免教人眷起悲哀。","占家宅人口有灾，失物难寻，病者保福，旧愿未还，求财微利，行人未至，官事留连，六甲难产，田蚕半熟，求官未达，婚不成，六畜有灾。"},
        new string[]{"第三十五签","大吉","鹤鸣九霄","鹤鸣霄汉气冲天，九万程途咫尺间。官位日升财禄进，安居吉庆度时年。","几年松下惜翎毛，不肯低头谒富豪。今日奋身腾碧汉，才知志气比天高。","檐前喜鹊噪声频，报汝今年百事宁。不但田蚕收十倍，更於门户发光明。","松间仙鹤本来孤，月里嫦娥岂有夫。夫子欲求鸳偶事，待看春色满皇都。","何期一失路迢遥，死活如今尚未消。再告神天阴保佑，能知踪迹在阶桥。","叮咛嘱咐不须忧，讼至公厅不自由。幸有高人亲着力，更无名字到皇州。","遥想家书抵万金，今朝报汝放宽心。程途须远家乡近，门外马嘶人自临。","灾来本是去西天，汝有阴功尚可延。不怕方隅神杀重，如今只要愿心坚。","占家宅人口吉利，自身无事，失物可寻，求财遂，病者恍惚重，行人立至，官事有理，求官得位，婚姻迟，六甲生男，田蚕大熟，六畜兴旺。"},
        new string[]{"第三十六签","上上","鱼翻桃浪","鱼翻桃浪当三月，此时方喜变龙身。求官得位须前定，百事无忧喜庆新。","先将一本报君知，秋到经营遂意迟。若遇三阳开泰日，须知名利正当时。","瑞气迎门百事新，相逢贵客自相亲。秋冬若有淹留滞，春夏人财总遂心。","天配姻缘合两头，那堪相许又相谋。水清看见鱼游戏，好把丝纶下钓钩。","略知踪迹又潜藏，休赖平人未见赃。失物要知何日得，且看辰已卯寅当。","笑聚山林凶恶稠，良善何必苦煎忧。主人大笑出门去，不用干戈盗贼休。","不记当初要脱身，如今求我问行人。行人若要归来日，再待牛羊逐鼠辰。","旦夕灾危吉有之，莫忧久病费支持。设吞药饵恐伤命，不若收心且待迟。","占家宅人口平安，占身吉庆，失物不失，病者自安，官事有理，求财遂意，行人有信，求官必达，六甲生男，田蚕大熟，六畜兴旺大吉，婚姻和合。"},
        new string[]{"第三十七签","下下","渡水无船","渡水无船岂可过，波涛汹浪势嵯峨。出入不宜须守旧，进之不得退无他。","天理於人岂在忙，见他富贵便心慌。君今若要求名利，且去乌江问霸王。","无事何须出外游，恐招火盗反为忧。今春切忌灾人口，要得平安只待秋。","眼下心思欲便成，岂知年命不相登。如今若要寻人口，且待黄河九波澄。","失物分明在岸边，要寻只为汝无缘。归家自把心量度，敢是时乖莫怨天。","莫将文字入官凶，恐被牵连到狱中。不若抽身归去好，任他风雨遍西东。","慢劳回首望青天，去客淹留在路边。咫尺有如千里远，音稀信杳苦相煎。","有方无药病难安，问卜求神说祸端。及早归家修善福，莫教加证变脾寒。","占家宅人口不利，自身守旧谨慎，失物不见，病者缠绵作福，求财未遂，行人未至，官事不利，求官未达，婚姻不成，六甲有灾，田蚕半熟，六畜损失。"},
        new string[]{"第三十八签","大吉","红日当天","红日当天照万方，无幽不烛遍余光。君子进身须显达，荣华富贵又安康。","天理人心两不违，自然合道脱昏迷。太平更感神明佑，南北东西任所为。","君家阴德合天门，岁小淹留祸不侵。六畜人财且休问，平安无事值千金。","鸳鸯飞入凤凰巢，莫教傍人背后唆。自是有缘天配合，不看年命也谐和。","失物如今未落空，休将闲气恼心中。急寻直向南头去，自有傍人说实踪。","自古才高气亦高，何须分诉口叨叨。前头自有高人力，不枉工夫走一遭。","旧约虽违莫怨嗟，行人已自离天涯。如今不必倚门望，巳午逢羊便到家。","小病缠身莫谩看，恐加潮热变脾寒。如今正是灾星照，不肯修禳难保安。","占家宅人口昌隆，失物得见，占病作福不妨，求财大遂，官事有理，行人立至，婚姻可成，六甲生男，田蚕大熟，六畜兴旺，君子加官进职。"},
        new string[]{"第三十九签","下下","忽入深山","忽入深山去路迷，不如归去失狐疑。进退出行俱不利，切须防慎暗中欺。","走遍天涯事未成，才成又着一场惊。不如守旧随缘过，春到人间枯木荣。","畜产衰嬴人眷廷，无端怪梦乱昏黄。汝今且待秋成后，好把门庭向日更。","昨种芝兰岂便芳，谁知嫩草不经霜。日今若得成婚眷，入舍还忧不久长。","汝忧失去问知风，只是难寻未落空。退步宽心终得见，不然惹起闹轰轰。","有理番成失理亏，吁嗟好事到头非。托人劝解方为吉，免得牵连到狱闱。","若问行人尚未还，忙忙回首已乡关。行非恩恋归来晚，只为丝丝事挂攀。","俟求药饵罔求神，疾病恹恹朱脱身。斗下有功灾可度，便教久病顿然轻。","占家宅防失脱，自身防口舌，阴人小口有灾，失物不见，占病保福，求财未遂，行人未至，官事不利，求官未达，婚姻难成，六甲生女虚惊，田蚕半收，六畜损失。"},
        new string[]{"第四十签","大吉","鸿鹄摩天","鸿鹄摩天势自然，未逢时至致灾悠。此日升腾还自在，翱翔直上九重天。","时逢暖律景和平，谋望求财总遂心。若要营为当此际，管教奋发取功名。","无移无定怪无凶，莫把闲愁挂腹中。自有福神阴力佑，秋冬财喜两三重。","前生原是汝家人，今世相逢又做亲。争奈目今时未至，且宜宽慢待人成。","失去资财却自忙，只因不肯细堤防。如今失却无回路，终有傍人说信方。","吾今报汝不须忧，官事虽凶未到头。但得贵人问口笑，不教贤者写供由。","几度阳关去问津，未知音信寄何人。如今不必登楼望，久客归期在酉辰。","未遇良医病不除，家财消乏莫嗟吁。但要五湖明月在，不愁无处获金珠。","占家宅自身出入吉利，失物难寻，终久见，病者服药，求财遂意，行人立至，官事有理，求官必达，六甲生男，田蚕大熟，六畜旺相，婚姻成迟。"},
        new string[]{"第四十一签","下下","落花流水","落花流水两无情，家宅忧疑主不宁。小口阴人招疾厄，切须急祷告神明。","当时有意逐东流，欲往蓬莱谒十州。不肯回头归旧业，却教埋没入荒址。","鬼怪无端绕户庭，向声怪梦使人惊。要知因甚人财赛，只为门前路不平。","休想斯人到汝家，莫教执迷起咨嗟。落花有意随流水，流水无情恋落花。","家人报汝有忧惊，梦里耽迷不自醒。已失且宜低着忍，休教冒认失人情。","暗室亏心天地知，何须临事告神祇。有理未成宜退步，恐遭刑宪悔来迟。","非是其人不恋家，只因阻隔在天涯。敬寻无路终朝望，十二巫山锁暮霞。","运赛时乖不自由，灾来只为苦贪求。月过十五光明少，人到终年万事休。","占家宅自身不利，失物不见，行人未至，占病作福，六甲生女有惊，田蚕不收，六畜损失，凡事不利。"},
        new string[]{"第四十二签","大吉","游鱼戏水","游鱼戏水出波间，跳跃优游岂等闲。喜遇泰来通万事，更无险难向於前。","地冷天寒水冻冰，安心守志乐清贫。如今喜遇阳和至，四海遨游任往行。","今年春夏事如何，人口无忧畜产多。秋末冬初岁小悔，更宜祈福保平和。","天与姻缘两利宜，那堪相许莫相违。他时共得成连理，似水如鱼岂暂离。","失去何须心下忙，只因无事少堤防。要知踪迹归何处，祗在溪边水岸傍。","小人里怪起无端，良善慌慌心胆寒。天理岂容人事变，不教直者受欺瞒。","困旅穷途羁绊间，去时容易转时难。伊今要问归期日，直待鱼龙出浅滩。","天星不顺被灾愆，何用临危告圣贤。但要汝心存善念，能教百病自然痊。","占家宅人口平安，自身出入吉利，求财得遂，行人欲至，求官得位，官事得理，婚姻和合，六甲生男，田蚕大熟，六畜兴旺，凡事大吉。"},
        new string[]{"第四十三签","上吉","日出扶桑","日出扶桑万里明，贵人喜气自亨通。求财谋望称心意，若问求官定有名。","几番辛苦起二更，只为平生利与名。喜得太阳东海出，光明无处不亨通。","福星高照汝家门，些小忧危不必论。人口田蚕思欲稳，神前多把好香焚。","如今喜得自投机，正好成婚过礼仪。两下相求无别虑，休题年长与年抵。","东西古路旧林前，失去踪由在里边。死物依然生活物，不须怨怅把人冤。","是非无故陷平人，何用忧心怯杖刑。自有贵人来喝散，终无囚狱不须惊。","故人久去在天涯，万水千山未到家。今日雁传音信至，平安报到免咨嗟。","平安无事不烧香，直待临危告上苍。汝病欲求痊可日，除非舍去世间脏。","占家宅人口平安，自身有喜，失物不失，病者不妨，求财大利，行人有信，官事有理，求官得位，婚姻可成，六甲生男，田蚕大熟，六畜兴旺。"},
        new string[]{"第四十四签","中下","乌云遍月","乌云遍月恰朦胧。暗里门庭事未中。只宜守旧方为吉，直待云开万事通。","本是聪明豁达人，恰如明月被乌云。等闲借得东风力，吹散浮云月再明。","户冷门衰百怪生，人离财散梦魂惊。如今若问平安日，除是修心学道经。","本来婚姻要团圆，争奈傍人乱闹喧。早定不如迟定好，宁教达者受孤眠。","莫将小事恶心中，神怒人嫌难见踪。且去南方寻旧迹，如今不必乱槌胸。","休争闲气起官灾，到彼应无乾争来。孰若平和回首去，不然牵绊入牢围。","音书未许寄来频，岂料中途鸦失群。等到鹦呜犬吠日，行人方脱万重云。","祸福无门自惹来，七情深染便生灾。如今若要心安乐，广布阴功舍施财。","占家宅人口不安，自身防小口，失物不见，占病宜作福，求财未遂，行人未至，官事失理宜和，求官未达，婚姻难成，六甲生女，田蚕半收，六畜损失。"},
        new string[]{"第四十五签","中平","风雷鼓舞","风雷鼓舞播乾坤，万物萌芽此日新。君子求谋皆遂意，庶人迪吉显家门。","秋后春前欲利名，机关用尽事难成。君能守得东风至，垫奋升腾枯木荣。","勤修香火福神欢，瘟疾无侵邪不干。春夏累逢层吻事，秋冬方喜进平安。","天婚本是宿时缘，休听傍人胡乱传。怠慢迁延三五日，琵琶抱入别人船。","自从失去不知风，问卜求神尽是空。惟有本心阴德重，如今踪迹在西东。","初然声势好惊人，良善慌慌意不盗。若得洞庭归去后，风和浪静放船行。","傍人传说不相同，去后音书不见踪。幸是本家阴骘重，分明人在泰和中。","心烦骨热更皮寒，咒咀冤家起祸端。早向神天求谢过，能令百病自然安。","占家宅人口平安，自身无事，失物可寻，病者自痊，求财遂意，行人便至，官事有理，贵人扶持，求官显达，六甲生男，田蚕大熟。婚姻忽成，百事大吉。"},
        new string[]{"第四十六签","下下","腾蛇入梦","腾蛇入梦主忧疑，防慎家门有贼欺。将来革过方为吉，进退如今未遇时。","心南意北枉清排，悔气如今尚未开。名利欲求非此日，宽心守旧待时来。","六畜有时作怪声，无端恶梦又惊人。要知因甚人多事，只为人求少福神。","眷属无途轻易逢，也应说过两三重。纵然勉强成亲后，只恐相逢是梦中。","梦中曾报有惊疑，不觉堤防引盗窥。已失要寻难得见，若经官府反招非。","人鬼交横事未谐，如今急急早安排。见官不如私和好，嬴得之时也损财。","坐想行思去路赊，重山阻隔未还家。如今要见亲人面，直待蟾光转海涯。","苦病缠身不可当，投医无效好难量。欲得不如南柯梦，你是修身作善良。","占家宅不盗，自身防口舌，失物难寻，病者保福，六甲生女虚惊，求财未遂，官事失理，求官未达，婚姻不成，行人未至，田蚕半收，六畜损失。"},
        new string[]{"第四十七签","中平","密云不雨","密云不雨尚蒙苍，却主忧疑亦不妨。更有小人来害己，家门暗昧事须防。","否泰相兼理自然，莫忧运用久淹留。有时借得春风力，吹散浮云见碧天。","门庭暗昧鬼邪多，人眷惊忧怎奈何。要得平安须祭祖，将心更改念弥陀。","婚姻前定莫强为，纵若强为久后非。此虏不留须别虏，何劳着意惹耽迷。","堪笑浮生空自忙，不知天纲暗中张。荣枯得失皆前定，自古浮生不久长。","官事悠悠不肯休，叮咛嘱汝不须忧。若逢龙虎交逢日，不用干戈也自休。","远望行人信息稀，不知凶吉致狐疑。如今若问真消息，蛇马逢牛是到期。","偶然无事忽遭愆，定是亡人要纸钱。有愿在心宜早赛，莫教淹滞在床眠。","占家宅人口有小灾不宁，自身防口舌，占失物不见，行人未至，病者作福，求财未遂，官事留连，求官未达，婚姻不成，六甲生女，田蚕半收。"},
        new string[]{"第四十八签","大吉","宝剑新磨","宝剑新磨益见光，东西照耀倍寻常。从前自有根基在，润色增明声播扬。","百炼千磨过此身，几年静里困埃尘。如今借得良工力，官贵相逢喜见新。","凶灾已过福神来，莫虑家贫不发财。此去管教人畜旺，秋冬加倍百和谐。","重整罗衣越样新，汝思堪作自家人。岂知久后人心别，只恐菱花再染尘。","横祸飞来要破财，如今休把众人猜。有踪终是难全得，损折岁见可免灾。","自古饶人不是痴，事须有理也须迟。公厅自有真明镜，急速难分黑白时。","每遇音书未见真，空劳密意祷天神。要知去客平安事，直待龙蛇到始明。","天谴凡人怎得知，偶遭磨障费支持。如今急早求禳保，莫待临时悔后迟。","占家宅人口有小灾不妨，失物可寻，自身更改吉，行人未至有信，病者保禳，求财遂意，官事宜和，求官必达，婚姻再合，六甲生男，田蚕大熟，六畜兴旺。"},
        new string[]{"第四十九签","下下","群鸦集噪","群鸦集噪未为奇，防慎阴人口舌欺。退后之时方可免，不然事绪主忧疑。","休望羊羔美酒斟，鱼书疡信两沉沉。鹊巢已被乌鸦占，万计于谋枉费心。","口舌无端蓦地来，只因家宅有疑猜。归来急早求神福，免教人口受天灾。","休信傍人说得狂，莲花那比菊花香。好生回步重开眼，莫把乌鸦作凤凰。","自己当时不小心，如今失却便难寻。休教惹得傍人闹，受辱遭殃岂可禁。","喧哗闲事闹烘烘，久后忧疑主见凶。来到公厅分曲直，一场惊险遍虚空。","终签不利卜行人，客路忙忙未转身。中道有忧灾祸扰，早求洪福叩龙神。","灾病缠绵未得全，虔诚求福告神天。操心不改遭魔障，若得痊时也损钱。","占家宅阴人小口有灾，自身有口舌，失物不见，病者不安宜作福，行人未至，求官未达，求财未遂，官事虚惊，婚姻不成，六甲生女，六畜田蚕有损失。"}
    };

