    int NextInt(int maxExclusive)
    {
        if (maxExclusive <= 0) throw new ArgumentOutOfRangeException("maxExclusive");
        ulong range = (ulong)UInt32.MaxValue + 1UL;
        ulong limit = range - (range % (uint)maxExclusive);
        var bytes = new byte[4];
        uint value;
        do { secureRandom.GetBytes(bytes); value = BitConverter.ToUInt32(bytes, 0); } while ((ulong)value >= limit);
        return (int)(value % (uint)maxExclusive);
    }

    void LoadSpecialDeckSetting()
    {
        specialDeckUnlocked = false;
        try {
            if (!File.Exists(SpecialSettingsPath)) return;
            var settings = json.DeserializeObject(File.ReadAllText(SpecialSettingsPath, Encoding.UTF8)) as Dictionary<string, object>;
            if (settings != null && settings.ContainsKey("specialDeckUnlocked"))
                specialDeckUnlocked = Convert.ToBoolean(settings["specialDeckUnlocked"]);
        } catch { specialDeckUnlocked = false; }
    }

    void SaveSpecialDeckSetting()
    {
        try {
            Directory.CreateDirectory(Path.GetDirectoryName(SpecialSettingsPath));
            File.WriteAllText(SpecialSettingsPath, json.Serialize(new Dictionary<string, object> {
                { "specialDeckUnlocked", specialDeckUnlocked }
            }), Encoding.UTF8);
        } catch { }
    }

    void OnSpecialDeckChanged(object sender, EventArgs e)
    {
        if (specialToggleGuard) return;
        if (!chkSpecialTarot.Checked || specialDeckUnlocked) { ResetTarotSessions(); return; }
        specialToggleGuard = true;
        chkSpecialTarot.Checked = false;
        specialToggleGuard = false;
        if (!VerifySpecialDeckCode()) return;
        specialDeckUnlocked = true;
        SaveSpecialDeckSetting();
        specialToggleGuard = true;
        chkSpecialTarot.Checked = true;
        specialToggleGuard = false;
        ResetTarotSessions();
        MessageBox.Show(this,
            isEnglish ? "The special deck is now enabled on this device." : "特殊牌组已在本机解锁。",
            isEnglish ? "Special deck" : "特殊牌组", MessageBoxButtons.OK, MessageBoxIcon.Information);
    }

    bool VerifySpecialDeckCode()
    {
        using (var dialog = new Form()) {
            dialog.Text = isEnglish ? "Special deck verification" : "特殊牌组验证";
            dialog.FormBorderStyle = FormBorderStyle.FixedDialog;
            dialog.StartPosition = FormStartPosition.CenterParent;
            dialog.ClientSize = new Size(360, 145);
            dialog.MinimizeBox = false; dialog.MaximizeBox = false; dialog.ShowInTaskbar = false;
            var label = new Label { Text = isEnglish ? "Enter the verification code:" : "请输入验证码：", AutoSize = true, Left = 18, Top = 18 };
            var input = new TextBox { Left = 18, Top = 46, Width = 324, UseSystemPasswordChar = true };
            var verify = new Button { Text = isEnglish ? "Verify" : "验证", DialogResult = DialogResult.OK, Left = 164, Top = 92, Width = 82 };
            var cancel = new Button { Text = isEnglish ? "Cancel" : "取消", DialogResult = DialogResult.Cancel, Left = 260, Top = 92, Width = 82 };
            dialog.Controls.Add(label); dialog.Controls.Add(input); dialog.Controls.Add(verify); dialog.Controls.Add(cancel);
            dialog.AcceptButton = verify; dialog.CancelButton = cancel;
            while (dialog.ShowDialog(this) == DialogResult.OK) {
                if (input.Text == SPECIAL_DECK_CODE) return true;
                MessageBox.Show(dialog, isEnglish ? "Incorrect verification code." : "验证码不正确。",
                    dialog.Text, MessageBoxButtons.OK, MessageBoxIcon.Warning);
                input.Clear(); input.Focus();
            }
            return false;
        }
    }
