    void ConfigureDatePicker(DateTimePicker picker, bool refreshTimeOnOpen)
    {
        picker.HandleCreated += delegate(object s, EventArgs e) { HideDatePickerTodayCircle(picker); };
        picker.DropDown += delegate(object s, EventArgs e) {
            if (refreshTimeOnOpen) SetPickerTimeToNow(picker);
            HideDatePickerTodayCircle(picker);
        };
        if (refreshTimeOnOpen)
            picker.CloseUp += delegate(object s, EventArgs e) { SetPickerTimeToNow(picker); };
    }

    void SetPickerTimeToNow(DateTimePicker picker)
    {
        DateTime selected = picker.Value;
        DateTime now = DateTime.Now;
        picker.Value = new DateTime(selected.Year, selected.Month, selected.Day, now.Hour, now.Minute, now.Second);
    }

    void HideDatePickerTodayCircle(DateTimePicker picker)
    {
        if (!picker.IsHandleCreated) return;
        int styles = unchecked((int)SendMessage(picker.Handle, DTM_GETMCSTYLE, IntPtr.Zero, IntPtr.Zero).ToInt64());
        SendMessage(picker.Handle, DTM_SETMCSTYLE, IntPtr.Zero, new IntPtr(styles | MCS_NOTODAYCIRCLE));
    }

    void LoadLanguage()
    {
        try { isEnglish = File.Exists(LanguagePath) && File.ReadAllText(LanguagePath, Encoding.UTF8).Trim() == "en"; }
        catch { isEnglish = false; }
    }

    void SaveLanguage()
    {
        try {
            Directory.CreateDirectory(Path.GetDirectoryName(LanguagePath));
            File.WriteAllText(LanguagePath, isEnglish ? "en" : "zh", Encoding.UTF8);
        } catch { }
    }

    void ReplaceItems(ComboBox box, object[] items, int selected)
    {
        box.BeginUpdate(); box.Items.Clear(); box.Items.AddRange(items); box.EndUpdate();
        box.SelectedIndex = Math.Max(0, Math.Min(selected, box.Items.Count - 1));
    }

    object[] ToObjects(string[] values)
    {
        var result = new object[values.Length];
        for (int i = 0; i < values.Length; i++) result[i] = values[i];
        return result;
    }

