    void UpdateTraditionalInputVisibility(bool rebuildItems)
    {
        if (traditionalPnl == null) return;
        bool traditional = curModule >= 7 && curModule <= 13;
        bool almanac = curModule == 13;
        traditionalPnl.Visible = traditional;
        lblTraditionalDate.Visible = dtTraditional.Visible = traditional && !almanac;
        bool method = curModule == 10 || curModule == 12;
        lblTraditionalMethod.Text = isEnglish ? "Method:" : (curModule == 12 ? "地分方式：" : "起卦方式：");
        lblTraditionalMethod.Visible = cmbTraditionalMethod.Visible = method;
        if (method && (rebuildItems || cmbTraditionalMethod.Items.Count != (curModule == 12 ? 3 : 2))) {
            int old = Math.Max(0, cmbTraditionalMethod.SelectedIndex);
            object[] items = curModule == 12
                ? (isEnglish ? new object[] { "Time", "Branch", "Number" } : new object[] { "时间", "指定地分", "数字" })
                : (isEnglish ? new object[] { "Time", "Number" } : new object[] { "时间", "数字" });
            ReplaceItems(cmbTraditionalMethod, items, Math.Min(old, items.Length - 1));
        }
        bool number = method && cmbTraditionalMethod.SelectedIndex == (curModule == 12 ? 2 : 1);
        bool branch = curModule == 12 && cmbTraditionalMethod.SelectedIndex == 1;
        lblTraditionalNumber.Visible = numTraditional.Visible = number;
        lblTraditionalBranch.Visible = cmbTraditionalBranch.Visible = branch;
        lblTraditionalScope.Visible = cmbTraditionalScope.Visible = curModule == 11;
        lblAlmanacTopic.Visible = cmbAlmanacTopic.Visible = almanac;
        lblAlmanacStart.Visible = dtAlmanacStart.Visible = almanac;
        lblAlmanacEnd.Visible = dtAlmanacEnd.Visible = almanac;
    }

