    TraditionalAlgorithmResult CalculateSharedLiuYao(string q, DateTime date, bool forceRandom,
        List<Dictionary<string, object>> frozenThrows, out Dictionary<string, object> options)
    {
        options = new Dictionary<string, object>();
        options["question"] = q;
        foreach (var item in FocusOptions()) options[item.Key] = item.Value;
        AddFixedEast8Context(options);
        bool manual = !forceRandom && cmbUpperTrigram.SelectedIndex >= 0 && cmbLowerTrigram.SelectedIndex >= 0;
        if (manual) {
            options["generationMethod"] = "manual";
            options["yaos"] = SelectedLiuYaoValues();
        } else {
            options["generationMethod"] = "coins";
            options["coinThrows"] = frozenThrows ?? FrozenCoinThrows();
        }
        return traditionalEngine.Calculate("liuyao", date, json.Serialize(options));
    }

