        if (cmbQuestionCategory.SelectedIndex < 0 || cmbGender.SelectedIndex < 0) return "";
        string key = FOCUS_KEYS[cmbQuestionCategory.SelectedIndex];
        var details = new List<string>();
        if (cmbGender.SelectedIndex == 1) details.Add(isEnglish ? "Male" : "男测");
        if (cmbGender.SelectedIndex == 2) details.Add(isEnglish ? "Female" : "女测");
        if (key == "search") details.Add((isEnglish ? "Target: " : "寻") + (isEnglish
            ? new[]{"Elder","Peer","Junior","Property"}[cmbSearchTarget.SelectedIndex]
            : new[]{"长辈","平辈","晚辈","财物"}[cmbSearchTarget.SelectedIndex]));
