            liuyao == null ? "六爻纳甲：计算失败（" + liuyaoError + "）" : "【六爻纳甲】" + nl + liuyao.AiPromptSection
        });
        string[][] specs = {
            new string[] { "qimen", "奇门遁甲" }, new string[] { "liuren", "大六壬" },
            new string[] { "xiaoliuren", "小六壬" }, new string[] { "meihua", "梅花易数" },
            new string[] { "taiyi", "太乙神数" }, new string[] { "jinkoujue", "金口诀" }
        };
        Dictionary<string, object> frozenFocus = FocusOptions();
        foreach (string[] spec in specs) {
            var options = new Dictionary<string, object>();
            options["question"] = q;
            if (spec[0] == "meihua") options["method"] = "time";
            if (spec[0] == "taiyi") options["scope"] = "day";
            if (spec[0] == "jinkoujue") options["method"] = "time";
            foreach (var item in frozenFocus) options[item.Key] = item.Value;
            AddFixedEast8Context(options);
            try {
                TraditionalAlgorithmResult result = traditionalEngine.Calculate(spec[0], castDate, json.Serialize(options));
                sections.Add("【" + spec[1] + "】" + nl + (result.AiPromptSection == "" ? "计算失败（没有返回 AI Prompt 分段）" : result.AiPromptSection));
            } catch (Exception ex) { sections.Add(spec[1] + "：计算失败（" + ex.Message + "）"); }
        }
        sections.Add(""); sections.Add("【解读要求】");
        sections.Add("先分别尊重各体系自身规则，再综合共同指向与矛盾。不得为了得到一致结论而删去冲突信息。区分强共识、弱共识、单一体系提示和资料不足。只依据以上数据，不重新抽牌、掷骰或排盘。");
        copyText = string.Join(nl, sections); // 复制不含灵签
        var liuyaoHistory = new Dictionary<string, object> { { "coinThrows", coinThrows } };
        if (liuyao != null) {
            liuyaoHistory["methodVersion"] = liuyao.MethodVersion;
            liuyaoHistory["input"] = liuyao.Input;
            liuyaoHistory["calculatedFacts"] = liuyao.CalculatedFacts;
            liuyaoHistory["aiPrompt"] = liuyao.AiPrompt;
        }
        AddHistoryText(copyText + nl + qianHead + nl + "【六爻复算记录】" + json.Serialize(liuyaoHistory));
        txtOut.Clear();
        Append(copyText, FontStyle.Regular);
        Append(nl + nl, FontStyle.Regular); // 界面结果末尾附灵签正文；综合 Prompt 不含签文正文
        AppendQian(qs);
    }

    void DivineDate(string q)
    {
        DateTime castDate = DateTime.Now;
        string nl = Environment.NewLine;
        // 塔罗日期：抽牌最多25张，抽到首牌为止（结果只显示季节或时间段）
        var pool = new List<int>();
        for (int i = 4; i <= 55; i++) pool.Add(i);
        var drawn = new List<string>();
        string ace = null;
        for (int n = 1; n <= 25; n++) {
            int p = NextInt(pool.Count);
            string name = TAROT[pool[p]][0];
            pool.RemoveAt(p);
            drawn.Add(name);
            if (name == "权杖1" || name == "圣杯1" || name == "宝剑1" || name == "星币1") { ace = name; break; }
        }
        string tarotResult = null;
        if (ace == null) tarotResult = "一年内无（25张内未见 Ace 的自定义牌阵规则，不等同客观一年内必无）";
        else {
            string season = null;
            for (int r = 0; r < DATE12.Length; r++) {
                string[] row = DATE12[r];
                if (row[0] != ace) continue;
                season = row[1];
                if (tarotResult == null && drawn.Contains(row[2])) {
                    tarotResult = row[4];
                    for (int d = 5; d <= 9; d += 2)
                        if (drawn.Contains(row[d])) { tarotResult = row[d + 1]; break; }
                }
            }
            if (tarotResult == null) tarotResult = season + "季";
        }
        // 占星骰子日期：行星=基础时长，星座=计量单位，宫位=调整数字
        string[] p2 = PLANETS[NextInt(PLANETS.Length)];
        string[] s2 = SIGNS[NextInt(SIGNS.Length)];
        string[] h2 = HOUSES[NextInt(HOUSES.Length)];
        string body = "塔罗预测（自定义日期启发式；DATE12 水瓶区间源表存在重叠，未擅自改写）：" + tarotResult + nl + nl
                    + "占星预测" + nl
                    + "基础时长：" + p2[2] + nl
                    + "计量单位：" + s2[2] + nl
                    + "调整数字：" + h2[2];
        string[][] timingSpecs = {
            new string[] { "qimen", "奇门应期" }, new string[] { "liuren", "六壬应期" }, new string[] { "meihua", "梅花应期" }
        };
        var timingLines = new List<string>();
        var timingValues = new Dictionary<string, string>();
        foreach (string[] spec in timingSpecs) {
            var options = new Dictionary<string, object>();
            if (spec[0] == "meihua") options["method"] = "time";
            AddFixedEast8Context(options);
            try {
                TraditionalAlgorithmResult result = traditionalEngine.Calculate(spec[0], castDate, json.Serialize(options));
                string value = result.TimingSummary == "" ? "计算失败（没有返回应期摘要）" : result.TimingSummary;
                timingValues[spec[0]] = value; timingLines.Add(spec[1] + "：" + value);
            } catch (Exception ex) {
                string value = "计算失败（" + ex.Message + "）";
                timingValues[spec[0]] = value; timingLines.Add(spec[1] + "：" + value);
            }
        }
        body += nl + nl + "【应期参考】" + nl + string.Join(nl, timingLines.ToArray());
        var almanacOptions = new Dictionary<string, object>();
        almanacOptions["question"] = q;
        almanacOptions["topic"] = new[] { "marriage", "move", "opening", "contract", "travel", "medical", "study", "burial", "renovation", "custom" }[cmbAlmanacTopic.SelectedIndex];
        almanacOptions["startDate"] = dtAlmanacStart.Value.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
        almanacOptions["endDate"] = dtAlmanacEnd.Value.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
        almanacOptions["symbolicTiming"] = new Dictionary<string, object> {
            { "tarot", tarotResult }, { "astrology", "基础时长：" + p2[2] + "；计量单位：" + s2[2] + "；调整数字：" + h2[2] }
        };
        almanacOptions["traditionalTiming"] = new Dictionary<string, object> {
            { "qimen", timingValues["qimen"] }, { "liuren", timingValues["liuren"] }, { "meihua", timingValues["meihua"] }
        };
        AddFixedEast8Context(almanacOptions);
        string almanacPrompt = "";
        try {
            TraditionalAlgorithmResult almanac = traditionalEngine.Calculate("almanac", dtAlmanacStart.Value, json.Serialize(almanacOptions));
            body += nl + nl + (almanac.Display == "" ? "择日黄历：计算失败（没有返回盘面）" : almanac.Display);
            almanacPrompt = almanac.AiPrompt;
        } catch (Exception ex) { body += nl + nl + "择日黄历：计算失败（" + ex.Message + "）"; }
        copyText = almanacPrompt;
        AddHistory();
        txtOut.Clear();
        Append(body + nl + nl + "―― 简要说明 ――" + nl, FontStyle.Regular);
        Append("塔罗抽牌顺序", FontStyle.Bold);
        Append("：" + string.Join("、", drawn) + nl, FontStyle.Regular);
        Append("占星骰子", FontStyle.Bold);
        Append("：" + Cjk(p2[0]) + "、" + Cjk(s2[0]) + "、" + h2[0], FontStyle.Regular);
    }

    void SaveHistories()
    {
        try {
            Directory.CreateDirectory(Path.GetDirectoryName(HistoryPath));
            var lines = new List<string>();
            for (int i = 0; i < histories.Length; i++) {
                foreach (string item in histories[i]) {
                    string data = Convert.ToBase64String(Encoding.UTF8.GetBytes(item));
                    lines.Add(i.ToString() + "|" + data);
                }
            }
            File.WriteAllLines(HistoryPath, lines.ToArray(), Encoding.UTF8);
        } catch { }
    }

    void LoadHistories()
    {
        try {
            if (!File.Exists(HistoryPath)) return;
            string[] lines = File.ReadAllLines(HistoryPath, Encoding.UTF8);
            foreach (string line in lines) {
                int pos = line.IndexOf('|');
                if (pos <= 0) continue;
                int idx;
                if (!int.TryParse(line.Substring(0, pos), out idx)) continue;
                if (idx < 0 || idx >= histories.Length) continue;
                string item = Encoding.UTF8.GetString(Convert.FromBase64String(line.Substring(pos + 1)));
                histories[idx].Add(item);
                if (histories[idx].Count > 30) histories[idx].RemoveAt(0);
            }
        } catch { }
    }

