    void OnDivine(object sender, EventArgs e)
    {
        string focusKey = cmbQuestionCategory.SelectedIndex >= 0 ? FOCUS_KEYS[cmbQuestionCategory.SelectedIndex] : "";
        if (curModule != 13 && (focusKey == "loveSingle" || focusKey == "lovePartner" || focusKey == "marriage") && cmbGender.SelectedIndex <= 0) {
            MessageBox.Show(this, isEnglish ? "Please select a gender for love or marriage questions." : "婚恋／婚姻类必须选择性别。",
                isEnglish ? "Question type" : "所测何事", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }
        if (curModule == 1) {
            bool hasMoving = Array.Exists(movingLineChecks, c => c.Checked);
            bool hasManual = cmbUpperTrigram.SelectedIndex >= 0 || cmbLowerTrigram.SelectedIndex >= 0 || hasMoving;
            if (hasManual && (cmbUpperTrigram.SelectedIndex < 0 || cmbLowerTrigram.SelectedIndex < 0)) {
                MessageBox.Show(this, isEnglish ? "Select both upper and lower trigrams for a manual casting." : "手动起卦请同时选择上卦和下卦。",
                    isEnglish ? "I Ching" : "六爻", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }
        }
        string q = txtQ.Text.Trim();
        if (q.Length == 0) q = isEnglish ? "(No question entered)" : "（未填写问题）";
        DoDivine(q);
        SaveState();
    }

    void DoDivine(string q)
    {
        if (curModule == 0) { DivineHome(q); return; }
        if (curModule == 1) { DivineSharedLiuYao(q); return; }
        if (curModule == 6) { DivineQian(q); return; }
        if (curModule == 2) { DivineTarot(q); return; }
        if (curModule == 14) { DivineOracle(q); return; }
        if (curModule == 13) { DivineDate(q); return; }
        if (curModule >= 7 && curModule <= 13) { DivineTraditional(q); return; }
        var lines = new List<string[]>();
        string result;
        if (curModule == 3) result = DivineLenormand(lines);
        else if (curModule == 4) result = DivineRunes(lines);
        else result = DivineAstro(lines);
        copyText = CopyBlock(q, (isEnglish ? MODULE_NAMES_EN : MODULE_NAMES_ZH)[curModule], result);
        string nl = Environment.NewLine;
        txtOut.Clear();
        AddHistory();
        Append(copyText + nl + nl + "―― 简要说明 ――" + nl, FontStyle.Regular);
        for (int i = 0; i < lines.Count; i++) {
            Append(lines[i][0], FontStyle.Regular);
            Append(lines[i][1], FontStyle.Bold);
            Append("：" + lines[i][2] + "。", FontStyle.Regular);
            if (lines[i][3].Length > 0) Append(lines[i][3], FontStyle.Italic);
            if (i < lines.Count - 1) Append(nl, FontStyle.Regular);
        }
    }

